package com.taktak.controller;
import com.taktak.service.RewardService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal;
@RestController @RequestMapping("/api/cafes/{slug}/rewards") @RequiredArgsConstructor public class RewardController {private final RewardService service;@GetMapping("/campaign")public RewardService.CampaignView get(@PathVariable String slug){return service.getCampaign(slug);}@PutMapping("/campaign")public RewardService.CampaignView save(@PathVariable String slug,@RequestBody RewardService.CampaignRequest body){return service.saveCampaign(slug,body);}@PostMapping("/feedback")public RewardService.CouponView feedback(@PathVariable String slug,@RequestBody RewardService.FeedbackRequest body){return service.feedback(slug,body);}@PostMapping("/coupons/validate")public RewardService.ValidationView validate(@PathVariable String slug,@RequestBody ValidateRequest body){return service.validate(slug,body.code(),body.amount());}@PostMapping("/coupons/manual")public RewardService.ManualCouponView manual(@PathVariable String slug,@RequestBody RewardService.ManualCouponRequest body){return service.createManualCoupon(slug,body);}public record ValidateRequest(String code,BigDecimal amount){} }
